<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';import {api,allPages,fmtDate} from '../services/api';import {usePage} from '../services/usePage';import Notice from '../components/Notice.vue';import StatusBadge from '../components/StatusBadge.vue';import EmptyState from '../components/EmptyState.vue'
const rows=ref<any[]>([]);const {error,success,busy,act}=usePage();let timer:ReturnType<typeof setInterval>;const load=async()=>{rows.value=await allPages('jobs/')};onMounted(()=>{act(load);timer=setInterval(()=>{if(!busy.value)act(load)},5000)});onBeforeUnmount(()=>clearInterval(timer));const retry=(id:string)=>act(async()=>{await api.post(`jobs/${id}/retry/`);await load()},'Trabajo reenviado.');const names:Record<string,string>={training:'Entrenamiento',inference:'Inferencia',preprocessing:'Preprocesamiento',evaluation:'Evaluación'}
</script>
<template><h1 class="heading">Procesos del laboratorio</h1><p class="subheading mb-7">Seguimiento de tareas. Actualización automática cada cinco segundos.</p><Notice :error="error" :success="success"/><div v-if="rows.length" class="space-y-4"><section v-for="j in rows" :key="j.id" class="card"><div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="font-semibold">{{names[j.kind]||j.kind}} <span class="ml-2 text-xs font-normal text-slate-400">{{j.id.slice(0,8)}}</span></h2><p class="mt-1 text-xs text-slate-400">{{fmtDate(j.created_at)}}</p></div><div class="flex items-center gap-3"><StatusBadge :value="j.state"/><button v-if="['queued','failed'].includes(j.state)" @click="retry(j.id)" class="btn-secondary" :disabled="busy">Reenviar</button></div></div><progress :value="j.progress" max="100" class="mt-5 h-2 w-full accent-emerald-700"></progress><p v-if="j.error" class="mt-3 break-words text-xs text-red-700">{{j.error}}</p><details v-if="Object.keys(j.result).length" class="mt-3 text-xs text-slate-500"><summary>Resultado del trabajo</summary><pre class="mt-2 overflow-auto rounded-xl bg-slate-50 p-3">{{JSON.stringify(j.result,null,2)}}</pre></details></section></div><EmptyState v-else title="No hay trabajos todavía" text="Los procesamientos, entrenamientos e inspecciones se registrarán aquí."/></template>
